use crate::clipper2::{FillRule, Path64, Paths64, Point64};

pub fn area(path: &Path64) -> f64 {
    if path.len() < 3 {
        return 0.0;
    }

    let mut twice_area: i128 = 0;
    for index in 0..path.len() {
        let current = path[index];
        let next = path[(index + 1) % path.len()];
        twice_area += (current.x as i128 * next.y as i128) - (next.x as i128 * current.y as i128);
    }

    twice_area as f64 / 2.0
}

pub fn translate_paths(paths: &Paths64, delta_x: i64, delta_y: i64) -> Paths64 {
    paths
        .iter()
        .map(|path| {
            path.iter()
                .map(|point| Point64::new(point.x + delta_x, point.y + delta_y))
                .collect()
        })
        .collect()
}

pub fn union(subjects: &Paths64, fill_rule: FillRule) -> Paths64 {
    let mut xs: Vec<i64> = subjects
        .iter()
        .flat_map(|path| path.iter().map(|point| point.x))
        .collect();
    let mut ys: Vec<i64> = subjects
        .iter()
        .flat_map(|path| path.iter().map(|point| point.y))
        .collect();

    if xs.len() < 2 || ys.len() < 2 {
        return Vec::new();
    }

    xs.sort_unstable();
    xs.dedup();
    ys.sort_unstable();
    ys.dedup();

    let mut result = Vec::new();

    for x_pair in xs.windows(2) {
        let x0 = x_pair[0];
        let x1 = x_pair[1];
        if x0 == x1 {
            continue;
        }

        for y_pair in ys.windows(2) {
            let y0 = y_pair[0];
            let y1 = y_pair[1];
            if y0 == y1 {
                continue;
            }

            let sample_x2 = x0 as i128 + x1 as i128;
            let sample_y2 = y0 as i128 + y1 as i128;

            let filled = match fill_rule {
                FillRule::NonZero => {
                    subjects
                        .iter()
                        .map(|path| winding_number(path, sample_x2, sample_y2))
                        .sum::<i32>()
                        != 0
                }
                FillRule::EvenOdd => {
                    subjects
                        .iter()
                        .filter(|path| point_in_path_even_odd(path, sample_x2, sample_y2))
                        .count()
                        % 2
                        == 1
                }
            };

            if filled {
                result.push(vec![
                    Point64::new(x0, y0),
                    Point64::new(x1, y0),
                    Point64::new(x1, y1),
                    Point64::new(x0, y1),
                ]);
            }
        }
    }

    result
}

fn point_in_path_even_odd(path: &Path64, point_x2: i128, point_y2: i128) -> bool {
    let mut inside = false;

    for index in 0..path.len() {
        let a = path[index];
        let b = path[(index + 1) % path.len()];

        let ay2 = 2 * a.y as i128;
        let by2 = 2 * b.y as i128;
        let intersects = (ay2 > point_y2) != (by2 > point_y2);
        if !intersects {
            continue;
        }

        let lhs = (point_x2 - 2 * a.x as i128) * (by2 - ay2);
        let rhs = (2 * b.x as i128 - 2 * a.x as i128) * (point_y2 - ay2);
        if lhs < rhs {
            inside = !inside;
        }
    }

    inside
}

fn winding_number(path: &Path64, point_x2: i128, point_y2: i128) -> i32 {
    let mut winding = 0;

    for index in 0..path.len() {
        let start = path[index];
        let end = path[(index + 1) % path.len()];

        let start_y2 = 2 * start.y as i128;
        let end_y2 = 2 * end.y as i128;

        if start_y2 <= point_y2 {
            if end_y2 > point_y2 && is_left_of_edge(start, end, point_x2, point_y2) > 0 {
                winding += 1;
            }
        } else if end_y2 <= point_y2 && is_left_of_edge(start, end, point_x2, point_y2) < 0 {
            winding -= 1;
        }
    }

    winding
}

fn is_left_of_edge(start: Point64, end: Point64, point_x2: i128, point_y2: i128) -> i128 {
    let edge_x = end.x as i128 - start.x as i128;
    let edge_y = end.y as i128 - start.y as i128;
    let point_x = point_x2 - 2 * start.x as i128;
    let point_y = point_y2 - 2 * start.y as i128;
    edge_x * point_y - edge_y * point_x
}
